using System.Text.Json;
namespace LeoLauncher;
sealed record Recurrence(string Frequency,bool Active=true,DateOnly? GeneratedThrough=null);
sealed record DailyTask(string Id,string Title,DateOnly Day,DateTimeOffset Created,DateTimeOffset? Completed=null,DateTimeOffset? Reminder=null,DateTimeOffset? Notified=null,string? SeriesId=null,DateOnly? OccurrenceDay=null,Recurrence? Repeat=null,bool Deleted=false,string? MatchId=null,DateTimeOffset? MatchKickoff=null,bool MatchFollowSchedule=true,bool MatchReminderManaged=true,bool MatchTitleManaged=true,string? MatchStatus=null,DateTimeOffset? MatchUpdated=null,DateTimeOffset? SnoozedUntil=null,bool Important=false);
sealed record MatchPlan(DailyTask Task,bool Added);
sealed partial class TodoStore
{
    readonly string? path;List<DailyTask> records=new();bool corrupt;
    public List<DailyTask> Items=>records.Where(t=>t.Repeat==null&&!t.Deleted).ToList();
    public event Action? Changed;
    public string? Error{get;private set;}
    public TodoStore(string? file){path=file;try{if(file!=null&&(File.Exists(file)||File.Exists(file+".bak")||File.Exists(Path.Combine(BackupDirectory!,"latest.json"))))records=AtomicJson.Read(file,ValidateSnapshot,Path.Combine(BackupDirectory!,"latest.json"));}catch{corrupt=true;Error="清单文件无法读取，原文件已保留，请从提醒与备份恢复";}if(!corrupt)AutoBackup();if(!corrupt)try{EnsureThrough(DateOnly.FromDateTime(DateTime.Today).AddDays(35));}catch(Exception e)when(e is IOException or UnauthorizedAccessException){Error="重复事项暂未生成，请检查清单写入权限";}}
    void Commit(List<DailyTask> next,bool remember=true){if(corrupt)throw new IOException("清单文件损坏，原文件已保留，请先检查 leo-todos.json");AutoBackup();if(path!=null)AtomicJson.Write(path,JsonSerializer.Serialize(next));if(remember)RememberUndo(records,next);records=next;Error=null;LatestBackup();NotifyChanged();}
    void NotifyChanged(){if(Changed is {} changed)foreach(Action subscriber in changed.GetInvocationList())FeatureFaults.Run("清单列表刷新",subscriber);}
    static string Title(string title){title=title.Trim();if(title.Length==0||title.Length>200)throw new ArgumentException("事项请填写1到200个字");return title;}
    DailyTask Find(string id)=>Items.FirstOrDefault(t=>t.Id==id)??throw new ArgumentException("事项不存在");
    public DailyTask Add(string title,DateOnly day,DateTimeOffset? reminder=null){var task=new DailyTask(Guid.NewGuid().ToString("N"),Title(title),day,DateTimeOffset.Now,Reminder:reminder);Commit(records.Append(task).ToList());return task;}
    public Recurrence? RuleFor(string? series)=>series==null?null:records.FirstOrDefault(t=>t.Id==series&&t.Repeat!=null)?.Repeat;
    public DailyTask AddRepeating(string title,DateOnly day,string frequency,DateTimeOffset? reminder=null){if(frequency is not("daily" or "weekly"))throw new ArgumentException("重复方式仅支持daily或weekly");var template=new DailyTask(Guid.NewGuid().ToString("N"),Title(title),day,DateTimeOffset.Now,Reminder:reminder,Repeat:new(frequency));var end=DateOnly.FromDateTime(DateTime.Today).AddDays(35);Commit(Generate(records.Append(template).ToList(),day>end?day:end));return Items.First(t=>t.SeriesId==template.Id&&t.OccurrenceDay==day);}
    static DateTimeOffset? Shift(DateTimeOffset? reminder,DateOnly from,DateOnly to)=>reminder==null?null:new DateTimeOffset(reminder.Value.LocalDateTime.AddDays(to.DayNumber-from.DayNumber));
    static List<DailyTask> Generate(List<DailyTask> source,DateOnly through){var next=source.ToList();var keys=source.Where(t=>t.SeriesId!=null).Select(t=>t.SeriesId+":"+t.OccurrenceDay).ToHashSet();foreach(var rule in source.Where(t=>!t.Deleted&&t.Repeat?.Active==true)){var recurrence=rule.Repeat!;if(through<rule.Day||recurrence.GeneratedThrough>=through)continue;int first=recurrence.GeneratedThrough?.DayNumber+1??rule.Day.DayNumber;first=Math.Max(first,rule.Day.DayNumber);int step=recurrence.Frequency=="daily"?1:7;if(step==7)first+=(7-(first-rule.Day.DayNumber)%7)%7;for(int number=first;number<=through.DayNumber;number+=step){var date=DateOnly.FromDayNumber(number);if(keys.Add(rule.Id+":"+date))next.Add(new(Guid.NewGuid().ToString("N"),rule.Title,date,DateTimeOffset.Now,Reminder:Shift(rule.Reminder,rule.Day,date),SeriesId:rule.Id,OccurrenceDay:date));}int index=next.FindIndex(t=>t.Id==rule.Id);next[index]=rule with{Repeat=recurrence with{GeneratedThrough=through}};}return next;}
    public void EnsureThrough(DateOnly through){if(!records.Any(t=>!t.Deleted&&t.Repeat?.Active==true&&t.Day<=through&&(t.Repeat.GeneratedThrough==null||t.Repeat.GeneratedThrough<through)))return;Commit(Generate(records,through),false);}
    public void StopRepeating(string series,DateOnly after){var rule=records.FirstOrDefault(t=>t.Id==series&&t.Repeat!=null)??throw new ArgumentException("重复规则不存在");Commit(records.Select(t=>t.Id==series?t with{Repeat=rule.Repeat! with{Active=false}}:t.SeriesId==series&&t.Completed==null&&t.OccurrenceDay>after?t with{Deleted=true}:t).ToList());}
    public void SetImportant(string id,bool value){Find(id);Commit(records.Select(t=>t.Id==id?t with{Important=value}:t).ToList());}
    public void Toggle(string id){var task=Find(id);Commit(records.Select(t=>t.Id==id?t with{Completed=task.Completed==null?DateTimeOffset.Now:null}:t).ToList());}
    public void SetReminder(string id,DateTimeOffset? time,bool applyToSeries=false){var task=Find(id);if(!applyToSeries||task.SeriesId==null){Commit(records.Select(t=>t.Id==id?t with{Reminder=time,Notified=null,SnoozedUntil=null,MatchReminderManaged=t.MatchId==null&&t.MatchReminderManaged}:t).ToList());return;}var template=records.First(t=>t.Id==task.SeriesId);Commit(records.Select(t=>t.Id==template.Id?t with{Reminder=Shift(time,task.Day,template.Day)}:t.Id==id||t.SeriesId==task.SeriesId&&!t.Deleted&&t.Completed==null&&t.OccurrenceDay>=task.OccurrenceDay?t with{Reminder=Shift(time,task.Day,t.Day),Notified=null}:t).ToList());}
    static DateOnly DeferredDay(DailyTask task){var tomorrow=DateOnly.FromDateTime(DateTime.Today).AddDays(1);return task.Day>=tomorrow?task.Day.AddDays(1):tomorrow;}
    public DateOnly PostponeDay(string id)=>DeferredDay(Find(id));
    public int Postpone(IEnumerable<string> ids){var set=ids.ToHashSet();var selected=Items.Where(t=>set.Contains(t.Id)&&t.Completed==null).ToArray();var next=records.ToList();foreach(var task in selected){int i=next.FindIndex(t=>t.Id==task.Id);if(next[i].Deleted)continue;var target=DeferredDay(task);var sibling=task.SeriesId==null?null:next.FirstOrDefault(t=>t.Id!=task.Id&&t.SeriesId==task.SeriesId&&t.Day==target&&t.Completed==null&&!t.Deleted);if(sibling!=null){next[i]=next[i] with{Deleted=true};if(sibling.Reminder==null&&task.Reminder!=null){int siblingIndex=next.FindIndex(t=>t.Id==sibling.Id);next[siblingIndex]=sibling with{Reminder=Shift(task.Reminder,task.Day,target),Notified=null};}}else next[i]=next[i] with{Day=target,Reminder=Shift(task.Reminder,task.Day,target),Notified=null,SnoozedUntil=null,MatchFollowSchedule=task.MatchId==null&&task.MatchFollowSchedule,MatchReminderManaged=task.MatchId==null&&task.MatchReminderManaged};}if(selected.Length>0)Commit(next);return selected.Length;}
    public MatchPlan AddMatch(FootballMatch match,DateTimeOffset now){if(!match.TimeKnown||match.Kickoff<=now||match.State!="pre"||match.Status.Contains("POSTPON",StringComparison.OrdinalIgnoreCase)||match.Status.Contains("CANCEL",StringComparison.OrdinalIgnoreCase))throw new ArgumentException("仅可添加时间已确定且尚未开赛的比赛");if(string.IsNullOrWhiteSpace(match.Id))throw new ArgumentException("比赛缺少编号");string key="espn:"+match.Id;var existing=Items.FirstOrDefault(t=>t.MatchId==key);if(existing!=null)return new(existing,false);var reminder=match.Kickoff.AddMinutes(-10);if(reminder<now)reminder=now;var task=new DailyTask(Guid.NewGuid().ToString("N"),Title("看球 · "+FootballFeed.Name(match.Home)+" vs "+FootballFeed.Name(match.Away)),DateOnly.FromDateTime(match.Kickoff.LocalDateTime),DateTimeOffset.Now,Reminder:reminder,MatchId:key,MatchKickoff:match.Kickoff,MatchStatus:"scheduled",MatchUpdated:now);Commit(records.Append(task).ToList());return new(task,true);}
    public DailyTask[] Due(DateTimeOffset now)=>Items.Where(t=>t.Completed==null&&t.Reminder!=null&&t.Reminder<=now&&t.Notified==null).OrderBy(t=>t.Reminder).ToArray();
    public void MarkNotified(IEnumerable<string> ids,DateTimeOffset now){var set=ids.ToHashSet();Commit(records.Select(t=>set.Contains(t.Id)?t with{Notified=now}:t).ToList(),false);}
    public List<DailyTask> ForWeek(DateOnly day){var start=day.AddDays(-(((int)day.DayOfWeek+6)%7));return Items.Where(t=>t.Day>=start&&t.Day<=start.AddDays(6)).OrderBy(t=>t.Day).ThenBy(t=>t.Completed!=null).ThenBy(t=>t.Created).ToList();}
    public DailyTask? Delete(string id){var item=Items.FirstOrDefault(t=>t.Id==id);if(item!=null)Commit(item.SeriesId==null?records.Where(t=>t.Id!=id).ToList():records.Select(t=>t.Id==id?t with{Deleted=true}:t).ToList());return item;}
    public void Restore(DailyTask item){var current=records.FirstOrDefault(t=>t.Id==item.Id);if(current?.Deleted==true)Commit(records.Select(t=>t.Id==item.Id?item with{Deleted=false}:t).ToList());else if(current==null)Commit(records.Append(item).ToList());}
    public List<DailyTask> ForDay(DateOnly day)=>Items.Where(t=>t.Day<=day&&(t.Completed==null||DateOnly.FromDateTime(t.Completed.Value.LocalDateTime)==day||t.Day==day)).OrderBy(t=>t.Completed!=null).ThenBy(t=>t.Day).ThenBy(t=>t.Created).ToList();
}
